// AUTO-GENERATED — embedded, self-contained email assets (no relative paths, no
// external hosting). Regenerate with the scratchpad build script if the banner or
// signature icons change.
//
//   • BANNER_DATA_URI      — email-banner.png (landscape hero, "Carbon. Made.
//                            Simple."), resized to 600px wide (JPEG q74) and
//                            embedded as a data: URI so it renders offline in
//                            Apple Mail, iPhone Mail and Outlook desktop.
//   • SIGNATURE_ICON_DATA  — the signature's icons rasterised from SVG to PNG
//                            (SVG is unsupported in Gmail/Outlook) and embedded so
//                            the signature carries no relative "icons/…" paths.
//
// NOTE: Gmail web blocks data: image URIs. To make the banner + icons render in
// Gmail too, host the PNGs publicly and set REVENUE_EMAIL_BANNER_URL /
// REVENUE_SIGNATURE_ICON_BASE_URL — the template then swaps the data: URIs for
// the hosted URLs automatically.

/** The central marketing banner as a self-contained data: URI (600px wide JPEG). */
export const BANNER_DATA_URI =
  "data:image/jpeg;base64,";

/** Signature icons rasterised to PNG (keyed by the original "icons/<name>.svg"). */
export const SIGNATURE_ICON_DATA: Record<string, string> = {
  "map-pin": "data:image/png;base64,",
  "mail": "data:image/png;base64,",
  "phone": "data:image/png;base64,",
  "world": "data:image/png;base64,",
  "linkedin": "data:image/png;base64,",
  "logo": "data:image/png;base64,",
};
